#!/usr/bin/env bash
# Builds an optimized release binary at ./app.
set -euo pipefail
cd "$(dirname "$0")"

command -v go >/dev/null || { echo "go is required" >&2; exit 1; }
CGO_ENABLED=0 go build -trimpath -ldflags="-s -w" -o app .

package kv

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strconv"
	"strings"
)

// MaxValueBytes is the largest value the server accepts.
const MaxValueBytes = 1 << 20

const kvPrefix = "/kv/"

// Handler serves the key-value HTTP API backed by a Store.
type Handler struct {
	store *Store
}

// NewHandler returns a Handler backed by store.
func NewHandler(store *Store) *Handler {
	return &Handler{store: store}
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// Always drain the body first so error responses don't reset the connection.
	body, err := readBody(w, r)
	if err != nil {
		var tooLarge *http.MaxBytesError
		if errors.As(err, &tooLarge) {
			w.Header().Set("Connection", "close")
			writeError(w, http.StatusRequestEntityTooLarge)
			return
		}
		writeError(w, http.StatusBadRequest)
		return
	}

	// Route on the raw request target so percent-encoded or dot-segment
	// paths are judged exactly as sent.
	path := r.RequestURI
	switch {
	case path == "/health":
		h.health(w, r)
	case path == "/kv":
		h.list(w, r)
	case strings.HasPrefix(path, kvPrefix):
		key := path[len(kvPrefix):]
		if !validKey(key) {
			writeError(w, http.StatusBadRequest)
			return
		}
		h.item(w, r, key, body)
	default:
		writeError(w, http.StatusNotFound)
	}
}

func (h *Handler) health(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		methodNotAllowed(w, http.MethodGet)
		return
	}
	write(w, http.StatusOK, "text/plain; charset=utf-8", []byte("ok"))
}

func (h *Handler) list(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		methodNotAllowed(w, http.MethodGet)
		return
	}
	data, err := json.Marshal(h.store.Keys())
	if err != nil {
		log.Printf("encode keys: %v", err)
		writeError(w, http.StatusInternalServerError)
		return
	}
	write(w, http.StatusOK, "application/json", data)
}

func (h *Handler) item(w http.ResponseWriter, r *http.Request, key string, body []byte) {
	switch r.Method {
	case http.MethodGet:
		value, ok := h.store.Get(key)
		if !ok {
			writeError(w, http.StatusNotFound)
			return
		}
		write(w, http.StatusOK, "application/octet-stream", value)
	case http.MethodPut:
		status := http.StatusOK
		if h.store.Put(key, body) {
			status = http.StatusCreated
		}
		write(w, status, "", nil)
	case http.MethodDelete:
		if !h.store.Delete(key) {
			writeError(w, http.StatusNotFound)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	default:
		methodNotAllowed(w, http.MethodGet, http.MethodPut, http.MethodDelete)
	}
}

// readBody reads the whole request body, failing with *http.MaxBytesError
// if it exceeds MaxValueBytes.
func readBody(w http.ResponseWriter, r *http.Request) ([]byte, error) {
	if r.ContentLength > MaxValueBytes {
		return nil, &http.MaxBytesError{Limit: MaxValueBytes}
	}
	body := http.MaxBytesReader(w, r.Body, MaxValueBytes)
	defer body.Close()
	data, err := io.ReadAll(body)
	if err != nil {
		return nil, err
	}
	if data == nil {
		data = []byte{}
	}
	return data, nil
}

// validKey reports whether key matches [A-Za-z0-9_-]{1,64}.
func validKey(key string) bool {
	if len(key) == 0 || len(key) > 64 {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

func write(w http.ResponseWriter, status int, contentType string, body []byte) {
	hdr := w.Header()
	if contentType != "" {
		hdr.Set("Content-Type", contentType)
	}
	hdr.Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	if len(body) > 0 {
		if _, err := w.Write(body); err != nil {
			log.Printf("write response: %v", err)
		}
	}
}

func writeError(w http.ResponseWriter, status int) {
	w.Header().Set("X-Content-Type-Options", "nosniff")
	write(w, status, "text/plain; charset=utf-8", []byte(http.StatusText(status)))
}

func methodNotAllowed(w http.ResponseWriter, allowed ...string) {
	w.Header().Set("Allow", strings.Join(allowed, ", "))
	writeError(w, http.StatusMethodNotAllowed)
}

package kv

import (
	"bytes"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func do(t *testing.T, h http.Handler, method, target string, body []byte) *http.Response {
	t.Helper()
	var r io.Reader
	if body != nil {
		r = bytes.NewReader(body)
	}
	req := httptest.NewRequest(method, target, r)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec.Result()
}

func readAll(t *testing.T, resp *http.Response) string {
	t.Helper()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

func TestRoutes(t *testing.T) {
	h := NewHandler(&Store{})
	steps := []struct {
		method, target, body string
		status               int
		want                 string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/nope", "", 404, ""},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/bad.key", "", 400, ""},
		{"GET", "/kv/%41", "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("a", 65), "", 400, ""},
		{"PUT", "/kv/" + strings.Repeat("a", 64), "x", 201, ""},
		{"PUT", "/kv/b", "2", 201, ""},
		{"PUT", "/kv/b", "3", 200, ""},
		{"GET", "/kv/b", "", 200, "3"},
		{"PATCH", "/kv/b", "", 405, ""},
		{"POST", "/kv", "", 405, ""},
		{"GET", "/kv", "", 200, `["` + strings.Repeat("a", 64) + `","b"]`},
		{"DELETE", "/kv/b", "", 204, ""},
		{"DELETE", "/kv/b", "", 404, ""},
		{"GET", "/kv/b", "", 404, ""},
		{"PUT", "/kv/empty", "", 201, ""},
		{"GET", "/kv/empty", "", 200, ""},
	}
	for _, s := range steps {
		resp := do(t, h, s.method, s.target, []byte(s.body))
		if resp.StatusCode != s.status {
			t.Fatalf("%s %s: status %d, want %d", s.method, s.target, resp.StatusCode, s.status)
		}
		if got := readAll(t, resp); s.want != "" && got != s.want {
			t.Fatalf("%s %s: body %q, want %q", s.method, s.target, got, s.want)
		}
	}
}

func TestValueSizeLimit(t *testing.T) {
	h := NewHandler(&Store{})
	if resp := do(t, h, "PUT", "/kv/big", make([]byte, MaxValueBytes)); resp.StatusCode != 201 {
		t.Fatalf("1 MiB value: status %d, want 201", resp.StatusCode)
	}
	if resp := do(t, h, "PUT", "/kv/big", make([]byte, MaxValueBytes+1)); resp.StatusCode != 413 {
		t.Fatalf("oversized value: status %d, want 413", resp.StatusCode)
	}
}

// Package kv implements an in-memory key-value store and its HTTP API.
package kv

import (
	"slices"
	"sync"
)

// Store is a concurrency-safe in-memory map from keys to byte values.
// The zero value is ready to use.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// Get returns the value stored under key and whether it was present.
// The returned slice must not be modified.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Put stores value under key, reporting whether the key was newly created.
// The store takes ownership of value.
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.data == nil {
		s.data = make(map[string][]byte)
	}
	_, existed := s.data[key]
	s.data[key] = value
	return !existed
}

// Delete removes key, reporting whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.data[key]; !ok {
		return false
	}
	delete(s.data, key)
	return true
}

// Keys returns every key in ascending byte order.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.data))
	for k := range s.data {
		keys = append(keys, k)
	}
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

// Command app runs kvhttp, an in-memory HTTP/1.1 key-value server.
//
// Usage:
//
//	app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"kvhttp/internal/kv"
)

func main() {
	if len(os.Args) != 2 {
		usage()
	}
	port, err := strconv.Atoi(os.Args[1])
	if err != nil || port < 1 || port > 65535 {
		usage()
	}
	if err := run(port); err != nil {
		log.Fatal(err)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: app <port>")
	os.Exit(2)
}

func run(port int) error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	addr := net.JoinHostPort("127.0.0.1", strconv.Itoa(port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}

	srv := &http.Server{
		Handler:           kv.NewHandler(&kv.Store{}),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       60 * time.Second,
		WriteTimeout:      60 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    64 << 10,
	}
	srv.SetKeepAlivesEnabled(false)

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil && !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}
